delete from public.orders; update public.kv set value='[{"code":"KARZON10","type":"pct","value":10,"min":0,"active":true,"uses":0,"note":"خصم ١٠٪ على كل الطلبات"},{"code":"WELCOME50","type":"fixed","value":50,"min":500,"active":true,"uses":0,"note":"خصم ٥٠ ج.م للطلب الأول فوق ٥٠٠ ج.م"},{"code":"FREESHIP","type":"ship","value":0,"min":1000,"active":true,"uses":0,"note":"شحن مجاني فوق ١٬٠٠٠ ج.م"},{"code":"WINTER20","type":"pct","value":20,"min":3000,"active":false,"uses":0,"note":"خصم ٢٠٪ فوق ٣٬٠٠٠ ج.م (موقوف)"}]'::jsonb where key='coupons'; update public.stock s set qty=(x.e->>'stock')::int from (select jsonb_array_elements(value) e from public.kv where key='products') x where s.product_id=(x.e->>'id')::int; select (select count(*) from public.orders) o, (select sum(qty) from public.stock) st;